class BoundedQueue {
public:
    explicit BoundedQueue(size_t cap) : capacity_(cap) {}

    bool try_push(int v) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.size() >= capacity_) {
            return false;
        }
        queue_.push(v);
        cond_var_.notify_one();
        return true;
    }

    bool try_pop(int& out) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (queue_.empty()) {
            return false;
        }
        out = queue_.front();
        queue_.pop();
        cond_var_.notify_one();
        return true;
    }

private:
    std::queue<int> queue_;
    std::mutex mutex_;
    std::condition_variable cond_var_;
    size_t capacity_;
};
