def eval_expr(expr: str) -> int:
    """
    Evaluate an integer arithmetic expression with +, -, *, /, parentheses, and spaces.
    Integer division truncates toward zero.
    """
    # Remove all spaces
    expr = expr.replace(' ', '')

    pos = 0
    n = len(expr)

    def parse_expression():
        """Parse addition and subtraction (lowest precedence)."""
        nonlocal pos
        result = parse_term()
        while pos < n and expr[pos] in '+-':
            op = expr[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        """Parse multiplication and division (higher precedence)."""
        nonlocal pos
        result = parse_factor()
        while pos < n and expr[pos] in '*/':
            op = expr[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                # Truncate toward zero
                if result * right < 0:
                    result = -((-result) // right) if result < 0 else -(result // (-right))
                else:
                    result = result // right
        return result

    def parse_factor():
        """Parse numbers, parentheses, and unary minus."""
        nonlocal pos
        if pos < n and expr[pos] == '(':
            pos += 1  # skip '('
            result = parse_expression()
            if pos < n and expr[pos] == ')':
                pos += 1  # skip ')'
            return result
        elif pos < n and expr[pos] == '-':
            pos += 1  # skip '-'
            return -parse_factor()
        elif pos < n and expr[pos] == '+':
            pos += 1  # skip '+'
            return parse_factor()
        else:
            # Parse a number
            start = pos
            while pos < n and expr[pos].isdigit():
                pos += 1
            return int(expr[start:pos])

    return parse_expression()
